// Verification-only independent public-rule specification. Not compiled into Unity/client.
using System;
using System.IO;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Text;
class P1Spec {
class Rec { public string Text; public uint U(string k){var m=Regex.Match(Text,"\""+k+"\":([0-9]+)");return m.Success?uint.Parse(m.Groups[1].Value):0;} public int N(string k){var m=Regex.Match(Text,"\""+k+"\":([0-9]+)");return m.Success?int.Parse(m.Groups[1].Value):0;} public string S(string k){var m=Regex.Match(Text,"\""+k+"\":\"([^\"]+)\"");return m.Success?m.Groups[1].Value:"";} }
static string Bits(double x){return unchecked((ulong)BitConverter.DoubleToInt64Bits(x)).ToString("x16");}
static ulong chain;
static void Emit(string s){unchecked{foreach(byte b in Encoding.UTF8.GetBytes(s)){chain^=b;chain*=1099511628211UL;}}Console.WriteLine(s+"|hash="+chain.ToString("x16"));}
class Encounter { public int Hp=1000000, Progress,Left=240000,Result; public void Tick(bool defend,int enemies){if(Result!=0)return;Hp=Math.Max(0,Hp-enemies*100);Left=Math.Max(0,Left-50);if(defend)Progress+=50;Result=Hp==0?2:Progress>=180000?1:Left==0?3:0;} }
class Run {public int Stage=1,Node=1,Result,Clock,Revision=1,Hp=1000,Progress,Left=240000,Deadline=30000,NextOffer=2,Mask,Offer=1,Resolved,Rerolls=1,LastResult,Supply; public uint LastId; public int[] Choices={1,4,0}; public uint Rng; int runId,lastRun,lastOffer,lastOp,lastChoice; public Run(int seed,int id){runId=id;Rng=unchecked((uint)seed*2654435761U+4U);} uint Draw(){unchecked{Rng+=0x6d2b79f5;uint z=Rng;z=(z^(z>>15))*(z|1);z^=z+(z^(z>>7))*(z|61);return z^(z>>14);}}
void NewOffer(){var legal=new List<int>();for(int card=1;card<=6;card++){if((Mask&(1<<(card-1)))!=0)continue;if((card==2||card==3)&&(Mask&1)==0)continue;if(card>=5&&(Mask&8)==0)continue;legal.Add(card);}for(int i=0;i<3;i++){Choices[i]=0;if(legal.Count==0)continue;int j=(int)(Draw()%(uint)legal.Count);Choices[i]=legal[j];legal[j]=legal[legal.Count-1];legal.RemoveAt(legal.Count-1);}Offer=NextOffer++;Resolved=0;}
public int Request(Rec q){int requestedRun=q.N("runId")==0?runId:q.N("runId");if(requestedRun!=runId)return 3;uint id=q.U("id");int offer=q.N("offer"),op=q.N("op"),choice=q.N("choice");if(id==0||id<LastId)return 7;if(id==LastId)return requestedRun==lastRun&&offer==lastOffer&&op==lastOp&&choice==lastChoice?LastResult:7;int result;if(Stage!=1)result=4;else if(offer!=Offer||Resolved!=0)result=5;else if(op==4){if(choice!=0)result=6;else if(Rerolls==0)result=8;else{Rerolls--;NewOffer();result=1;}}else if(op==3){result=choice==0?1:6;if(result==1){Resolved=1;Supply=1;}}else if(op!=2||Array.IndexOf(Choices,choice)<0||choice>6)result=6;else{result=1;if(choice==0)Supply=1;else Mask|=1<<(choice-1);Resolved=1;}LastId=id;LastResult=result;lastRun=requestedRun;lastOffer=offer;lastOp=op;lastChoice=choice;Revision++;return result;}
public void Tick(){if(Stage==3)return;Clock+=50;if(Stage!=1)return;if(Clock>=Deadline&&Resolved==0){Resolved=1;Supply=1;}if(Resolved!=0){Stage=2;Revision++;}}
public void Finish(int result){Revision++;if(result!=1||Node==3){Stage=3;Result=result;}else{Node++;Stage=1;Deadline=Clock+30000;Hp=1000;Progress=0;Left=240000;NewOffer();}}
}
class Build {public int Mask,Stationary,Mag=1,Reserve=120,Count,Refund,Heal,Tempo,Mark,Stagger,State;public double Hp=50,Reload=9999,Timer;public bool Enabled; public Build(int index,bool enabled){Enabled=enabled;Mask=enabled?(index==6?63:1<<index):0;}bool Has(int n){return Enabled&&(Mask&(1<<(n-1)))!=0;}
public string Tick(int t,Rec e){int now=t*50;bool moving=e!=null&&e.N("moving")!=0;if(Enabled)Stationary=moving?0:Math.Min(1000,Stationary+50);double m=1;if(e!=null){bool head=e.N("head")!=0;int distance=e.N("distance");if(Has(1)){if(now<Mark)m*=1.5;else if(!head)m*=0.85;}if(Has(2)&&!head)m*=0.85;if(Has(3)){if(moving)m*=0.8;else if(Stationary>=1000&&head)m*=1.75;}for(int card=4;card<=6;card++)if(Has(card)&&distance>6)m*=0.8;
if(Has(2)&&head&&now>=Refund){Mag=Math.Min(12,Mag+1);Refund=now+500;Count++;}if(Has(4)&&distance<=6&&now>=Stagger){State=7;Timer=500;Stagger=now+2000;Count++;}if(Has(1)&&head){Mark=now+3000;Count++;}if(e.N("kill")!=0&&distance<=6){if(Has(6)&&now>=Tempo){Mag=12;Reload=0;Tempo=now+2000;Count++;}if(Has(5)&&now>=Heal){Hp=Math.Min(100,Hp+8);Heal=now+1000;Count++;}}}
return Mask+","+Stationary+","+Bits(m)+","+Bits(Hp)+","+Mag+","+Reserve+","+Bits(Reload)+","+Count+","+Refund+","+Heal+","+Tempo+","+Mark+","+Stagger+","+Bits(Timer)+","+State;}}
static int Main(string[] args){try{var cases=new List<Rec>();var requests=new List<Rec>();var events=new List<Rec>();foreach(string line in File.ReadAllLines(args[0])){var r=new Rec{Text=line};if(r.S("kind")!="")cases.Add(r);else if(line.Contains("\"offer\""))requests.Add(r);else if(line.Contains("\"head\""))events.Add(r);}foreach(var c in cases){string name=c.S("name"),kind=c.S("kind");chain=14695981039346656037UL;var run=new Run(c.N("seed"),c.N("runId"));var enc=new Encounter();var builds=new Build[7];for(int k=0;k<7;k++)builds[k]=new Build(k,name!="classic-neutral");for(int t=0;t<c.N("ticks");t++){string s="case="+name+"|tick="+t;if(kind=="run"){int ack=0;foreach(var q in requests)if(q.N("tick")==t)ack=run.Request(q);int before=run.Stage;run.Tick();if(run.Stage==2){if(before!=2)enc=new Encounter();enc.Tick(c.N("defended")!=0,c.N("invaders"));run.Hp=enc.Hp/1000;run.Progress=enc.Progress;run.Left=enc.Left;if(enc.Result!=0)run.Finish(enc.Result);}s+="|stage="+run.Stage+"|node="+run.Node+"|result="+run.Result+"|clock="+run.Clock+"|revision="+run.Revision+"|hp="+run.Hp+"|progress="+run.Progress+"|left="+run.Left+"|deadline="+run.Deadline+"|rng="+run.Rng+"|nextOffer="+run.NextOffer+"|mask="+run.Mask+"|offer="+run.Offer+"|choices="+string.Join(",",run.Choices)+"|resolved="+run.Resolved+"|rerolls="+run.Rerolls+"|lastId="+run.LastId+"|lastResult="+run.LastResult+"|supply="+run.Supply+"|ack="+ack;
}else if(kind=="encounter"){int inv=c.N("invaders");if(c.N("spikeInvaders")>0&&t==c.N("spikeTick"))inv=c.N("spikeInvaders");enc.Tick(c.N("defended")!=0,inv);s+="|hpMilli="+enc.Hp+"|progress="+enc.Progress+"|left="+enc.Left+"|result="+enc.Result;}else{Rec e=null;foreach(var item in events)if(item.N("tick")==t)e=item;for(int k=0;k<7;k++)s+="|b"+k+"="+builds[k].Tick(t,e);}Emit(s);}}return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 2;}}
}
